
import OpenAI from "openai";
import { env } from "../config/env.js";

const openai =
  env.LLM_PROVIDER === "openai"
    ? new OpenAI({
        apiKey: env.OPENAI_API_KEY!,
        timeout: 20_000,
        maxRetries: 1,
      })
    : null;

export async function generateAnswer(
  query: string,
): Promise<string> {
  if (env.LLM_PROVIDER === "mock") {
    return [
      "[DEMO MODE — MOCK RESPONSE]",
      "",
      `Your question: ${query}`,
      "",
      "This response is generated by the local mock provider,",
      "not by an actual AI model.",
      "",
      "The application successfully processed your query.",
      "Select LLM_PROVIDER=openai and configure a valid API key",
      "with available credits to receive a real AI-generated answer.",
    ].join("\n");
  }

  if (!openai) {
    throw new Error("OpenAI provider is not configured.");
  }

  const response = await openai.responses.create({
    model: env.OPENAI_MODEL,
    instructions:
      "You are a helpful AI query assistant. Answer clearly, accurately, and concisely. If you are uncertain, say so.",
    input: query,
  });

  const answer = response.output_text.trim();

  if (!answer) {
    throw new Error("The AI provider returned an empty response.");
  }

  return answer;
}
